import React, { useMemo, useState } from 'react';
import ComparisonTable from './components/ComparisonTable';
import './App.css';

const formatCurrency = (value) => {
  const n = Number(value);
  if (Number.isNaN(n)) return value;
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(n);
};

function App() {
  const [products, setProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSearch = (e) => setSearchTerm(e.target.value);

  const fetchProducts = async () => {
    if (!searchTerm.trim()) {
      setError('Please enter a product name');
      return;
    }

    setLoading(true);
    setError('');
    setProducts([]); // optional: clears old results when new search starts

    try {
      const response = await fetch(
        `http://localhost:5000/api/products?search=${encodeURIComponent(searchTerm)}`
      );
      const data = await response.json();

      if (!Array.isArray(data) || data.length === 0) {
        setError('No products found. Try another search.');
        setProducts([]);
        return;
      }

      setProducts(data);
    } catch (err) {
      setError('Error fetching products. Make sure backend is running.');
      console.error('Error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') fetchProducts();
  };

  // Winner logic
  const { bestPriceId, bestRatingId } = useMemo(() => {
    if (!products?.length) return { bestPriceId: null, bestRatingId: null };

    const toNum = (v) => {
      const n = Number(v);
      return Number.isNaN(n) ? Infinity : n;
    };

    let minPrice = Infinity;
    let maxRating = -Infinity;
    let minPriceId = null;
    let maxRatingId = null;

    for (const p of products) {
      const price = toNum(p.price);
      const rating = Number(p.rating);

      if (price < minPrice) {
        minPrice = price;
        minPriceId = p.id ?? `${p.name}-${p.source}-${p.link}`;
      }
      if (!Number.isNaN(rating) && rating > maxRating) {
        maxRating = rating;
        maxRatingId = p.id ?? `${p.name}-${p.source}-${p.link}`;
      }
    }

    return { bestPriceId: minPriceId, bestRatingId: maxRatingId };
  }, [products]);

  const skeletons = useMemo(() => Array.from({ length: 2 }), []);

  return (
    <div className="App">
      <header className="header">
        <div>
          <h1>🛍️ Product Comparison</h1>
          <p>Compare products from Amazon & Flipkart</p>
        </div>
      </header>

      <div className="search-container">
        <input
          type="text"
          placeholder="Search products (e.g., Laptop, Phone)..."
          value={searchTerm}
          onChange={handleSearch}
          onKeyPress={handleKeyPress}
        />
        <button onClick={fetchProducts} disabled={loading}>
          {loading ? 'Searching...' : 'Search'}
        </button>
      </div>

      {error && <div className="error-message">{error}</div>}

      {!loading && products.length > 0 && (
        <div className="results-summary">
          <p>
            Found <strong>{products.length}</strong> products
          </p>
        </div>
      )}

      <div className="products-container">
        {loading &&
          skeletons.map((_, i) => (
            <div key={i} className="product-card skeleton">
              <div className="sk-line sk-title" />
              <div className="sk-line sk-sub" />
              <div className="sk-line sk-price" />
              <div className="sk-line sk-rating" />
              <div className="sk-btn" />
            </div>
          ))}

        {!loading &&
          products.map((product) => {
            const key = product.id ?? `${product.name}-${product.source}-${product.link}`;
            const isBestPrice = key === bestPriceId;
            const isBestRating = key === bestRatingId;

            return (
              <div
                key={key}
                className={[
                  'product-card',
                  isBestPrice ? 'winner winner-price' : '',
                  isBestRating ? 'winner winner-rating' : '',
                ].join(' ')}
              >
                <div className="winnerRow">
                  {isBestPrice && <span className="winnerBadge">Best Price</span>}
                  {isBestRating && <span className="winnerBadge alt">Top Rated</span>}
                </div>

                <h3>{product.name}</h3>
                <p className="source">{product.source}</p>
                <p className="price">{formatCurrency(product.price)}</p>
                <p className="rating">⭐ {product.rating}/5</p>

                <a href={product.link} target="_blank" rel="noopener noreferrer">
                  View Product →
                </a>
              </div>
            );
          })}
      </div>

      {!loading && products.length > 0 && (
        <ComparisonTable
          products={products}
          bestPriceId={bestPriceId}
          bestRatingId={bestRatingId}
          formatCurrency={formatCurrency}
        />
      )}
    </div>
  );
}

export default App;
